mapper.select:
SELECT p.id, p.dept_id, d.dept_name, p.post_code, p.post_name, p.status FROM sys_post p INNER JOIN sys_dept d ON p.dept_id = d.id AND d.is_deleted = 0 WHERE p.is_deleted = 0
AND p.status = #{status}
AND ( p.post_code LIKE CONCAT(#{keyword}, '%') OR p.post_name LIKE CONCAT(#{keyword}, '%'))
ORDER BY p.order_num ASC, p.id DESC LIMIT #{limit}
